        tid=b"\xab\xcd"; flags=b"\x01\x00"; q= b"\x00\x01\x00\x00\x00\x00\x00\x00"
        qn=b"".join(bytes([len(p)])+p.encode() for p in name.split("."))+b"\x00"
        pkt=tid+flags+q+qn+b"\x00\x01\x00\x01"
